// ============ Scan (câmera com leitor nativo + ZXing de reforço) ============
function ScanView({ T, onDetected, onCancel }) {
  const videoRef = useRef(null);
  const streamRef = useRef(null);
  const detectorRef = useRef(null);
  const zxingControlsRef = useRef(null);
  const rafRef = useRef(null);
  const [status, setStatus] = useState("iniciando");
  const [erroMsg, setErroMsg] = useState("");
  const [manualMode, setManualMode] = useState(false);
  const [manualCode, setManualCode] = useState("");
  const [facing, setFacing] = useState("environment");
  const [torchOn, setTorchOn] = useState(false);
  const [torchDisponivel, setTorchDisponivel] = useState(false);

  const pararTudo = useCallback(() => {
    if (rafRef.current) cancelAnimationFrame(rafRef.current);
    if (zxingControlsRef.current) { try { zxingControlsRef.current.stop(); } catch {} zxingControlsRef.current = null; }
    if (streamRef.current) { streamRef.current.getTracks().forEach((t) => t.stop()); streamRef.current = null; }
  }, []);

  const scanLoopNativo = useCallback(() => {
    rafRef.current = requestAnimationFrame(async () => {
      if (videoRef.current && detectorRef.current && videoRef.current.readyState >= 2) {
        try {
          const codes = await detectorRef.current.detect(videoRef.current);
          if (codes && codes.length > 0) { pararTudo(); onDetected(codes[0].rawValue); return; }
        } catch {}
      }
      scanLoopNativo();
    });
  }, [onDetected, pararTudo]);

  function carregarZXing() {
    return new Promise((resolve, reject) => {
      if (window.ZXing) { resolve(window.ZXing); return; }
      const script = document.createElement("script");
      script.src = ZXING_CDN;
      script.async = true;
      script.onload = () => resolve(window.ZXing);
      script.onerror = () => reject(new Error("zxing-load-fail"));
      document.head.appendChild(script);
    });
  }
  function comTimeout(promessa, ms) {
    return Promise.race([
      promessa,
      new Promise((_, reject) => setTimeout(() => reject(new Error("timeout")), ms))
    ]);
  }

  const iniciarCamera = useCallback(async (facingAtual) => {
    setStatus("iniciando");
    setErroMsg("");
    pararTudo();

    // trava de segurança: se nada resolver em 12s (comum em Safari/iOS com script lento), cai pro modo manual
    const timeoutGeral = setTimeout(() => {
      setStatus((atual) => {
        if (atual === "iniciando") { setManualMode(true); setErroMsg("A câmera demorou demais para responder neste navegador."); return "erro"; }
        return atual;
      });
    }, 12000);

    // tenta a câmera preferida (frontal/traseira) com resolução ideal; se o navegador recusar
    // a restrição exata, tenta de novo de forma mais permissiva antes de desistir
    async function obterStream() {
      try {
        return await navigator.mediaDevices.getUserMedia({
          video: { facingMode: { ideal: facingAtual }, width: { ideal: 1280 }, height: { ideal: 720 } }
        });
      } catch {
        return await navigator.mediaDevices.getUserMedia({ video: true });
      }
    }

    try {
      const stream = await obterStream();
      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.play().catch(() => {}); // iOS pode rejeitar a promise mesmo funcionando; não bloqueia o fluxo
      }

      let capabilities = {};
      try { const track = stream.getVideoTracks()[0]; capabilities = track && track.getCapabilities ? track.getCapabilities() : {}; } catch {}
      setTorchDisponivel(!!capabilities.torch);
      setTorchOn(false);

      if ("BarcodeDetector" in window) {
        detectorRef.current = new window.BarcodeDetector({ formats: ["ean_13", "ean_8", "upc_a", "upc_e", "code_128", "code_39", "itf"] });
        clearTimeout(timeoutGeral);
        setStatus("ok");
        scanLoopNativo();
        return;
      }

      // navegador sem leitor nativo (ex: Safari/iOS): carrega leitor alternativo dinamicamente, com timeout próprio
      try {
        const ZXing = await comTimeout(carregarZXing(), 8000);
        const hints = new Map();
        // restringe aos formatos de código de barras de varejo (mais rápido e mais preciso que testar tudo, incl. QR)
        hints.set(ZXing.DecodeHintType.POSSIBLE_FORMATS, [
          ZXing.BarcodeFormat.EAN_13, ZXing.BarcodeFormat.EAN_8, ZXing.BarcodeFormat.UPC_A,
          ZXing.BarcodeFormat.UPC_E, ZXing.BarcodeFormat.CODE_128, ZXing.BarcodeFormat.CODE_39,
          ZXing.BarcodeFormat.ITF
        ]);
        hints.set(ZXing.DecodeHintType.TRY_HARDER, true);
        const codeReader = new ZXing.BrowserMultiFormatReader(hints);
        zxingControlsRef.current = await comTimeout(
          codeReader.decodeFromVideoElement(videoRef.current, (result) => {
            if (result) { pararTudo(); onDetected(result.getText()); }
          }),
          8000
        );
        clearTimeout(timeoutGeral);
        setStatus("ok");
      } catch {
        clearTimeout(timeoutGeral);
        setStatus("sem-suporte");
        setManualMode(true);
      }
    } catch (e) {
      clearTimeout(timeoutGeral);
      if (e && e.name === "NotAllowedError") setErroMsg("Permissão de câmera negada. Habilite o acesso nas configurações do navegador.");
      else if (e && e.name === "NotFoundError") setErroMsg("Nenhuma câmera foi encontrada neste dispositivo.");
      else setErroMsg("Não foi possível acessar a câmera.");
      setStatus("erro");
      setManualMode(true);
    }
  }, [onDetected, pararTudo, scanLoopNativo]);

  // Único ponto que liga/desliga a câmera: roda de novo sempre que voltamos do modo manual
  // (botão "voltar pra câmera" ou "tentar novamente") ou quando a câmera frontal/traseira é trocada.
  // Isso corrige o bug de tentar reiniciar a câmera antes do <video> existir na tela.
  useEffect(() => {
    if (!manualMode) iniciarCamera(facing);
    return () => pararTudo();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [facing, manualMode]);

  function alternarTorch() {
    const track = streamRef.current && streamRef.current.getVideoTracks()[0];
    if (!track) return;
    const novoEstado = !torchOn;
    track.applyConstraints({ advanced: [{ torch: novoEstado }] }).then(() => setTorchOn(novoEstado)).catch(() => {});
  }

  function submitManual() {
    const code = apenasNumeros(manualCode, 14);
    if (code.length < 4) return;
    pararTudo();
    onDetected(code);
  }

  return (
    <div className="px-4 pt-4">
      {!manualMode && (
        <div className="relative rounded-2xl overflow-hidden bg-black" style={{ aspectRatio: "3/4" }}>
          <video ref={videoRef} className="w-full h-full object-cover" muted autoPlay playsInline webkit-playsinline="true" />
          <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
            <div className="w-[78%] h-24 relative">
              <CornerGuide className="top-0 left-0" />
              <CornerGuide className="top-0 right-0" />
              <CornerGuide className="bottom-0 left-0" />
              <CornerGuide className="bottom-0 right-0" />
              <div style={{ background: RED }} className="absolute left-0 right-0 top-1/2 h-0.5 animate-pulse" />
            </div>
          </div>

          <div className="absolute top-3 right-3 flex flex-col gap-2">
            {torchDisponivel && (
              <button onClick={alternarTorch} className="h-9 w-9 rounded-full bg-black/50 flex items-center justify-center">
                {torchOn ? <Flashlight size={16} color="#FFD34D" /> : <FlashlightOff size={16} color="#fff" />}
              </button>
            )}
            <button onClick={() => setFacing((f) => (f === "environment" ? "user" : "environment"))} className="h-9 w-9 rounded-full bg-black/50 flex items-center justify-center">
              <SwitchCamera size={16} color="#fff" />
            </button>
          </div>

          {status === "iniciando" && (
            <div className="absolute inset-0 bg-black/60 flex flex-col items-center justify-center gap-2">
              <Loader2 className="animate-spin" color="#fff" size={26} />
              <p className="text-white text-xs">Abrindo câmera...</p>
            </div>
          )}
          <div className="absolute bottom-3 left-0 right-0 text-center">
            <p className="text-white/90 text-xs font-medium bg-black/40 inline-block px-3 py-1 rounded-full">Aponte para o código de barras</p>
          </div>
        </div>
      )}

      {status === "erro" && (
        <div style={{ background: RED_SOFT }} className="mt-3 rounded-lg px-3 py-2.5 flex items-start gap-2">
          <AlertTriangle size={14} color={RED_DARK} className="mt-0.5 shrink-0" />
          <div className="flex-1">
            <p className="text-xs font-medium" style={{ color: RED_DARK }}>{erroMsg}</p>
            <button onClick={() => { setManualMode(false); }} className="text-xs font-semibold mt-1.5 flex items-center gap-1" style={{ color: RED_DARK }}>
              <RotateCcw size={12} /> Tentar novamente
            </button>
          </div>
        </div>
      )}
      {status === "sem-suporte" && (
        <div className="mt-3">
          <p style={{ color: T.subtext }} className="text-xs text-center">Este navegador não suporta leitura automática. Digite manualmente.</p>
          <button onClick={() => setManualMode(false)} className="w-full text-xs font-semibold mt-1.5 flex items-center justify-center gap-1" style={{ color: BLUE }}>
            <RotateCcw size={12} /> Tentar carregar a câmera de novo
          </button>
        </div>
      )}

      {!manualMode ? (
        <button onClick={() => setManualMode(true)} className="w-full mt-4 flex items-center justify-center gap-2 text-sm font-medium py-3 rounded-xl border" style={{ borderColor: BLUE, color: BLUE }}>
          Digitar código manualmente
        </button>
      ) : (
        <div style={{ background: T.card, borderColor: T.border }} className="mt-4 rounded-xl p-4 border shadow-sm">
          <label style={{ color: T.subtext }} className="text-xs font-semibold mb-1.5 block">Código do produto (somente números)</label>
          <input autoFocus inputMode="numeric" pattern="[0-9]*" maxLength={14} value={manualCode}
            onChange={(e) => setManualCode(apenasNumeros(e.target.value, 14))} placeholder="Ex: 7891234567890"
            style={{ background: T.inputBg, color: T.text, borderColor: T.border }} className="w-full font-mono border rounded-lg px-3 py-2.5 text-sm outline-none focus:ring-2" />
          <p style={{ color: T.subtext }} className="text-[10px] mt-1">{manualCode.length}/14 dígitos {manualCode.length > 0 && manualCode.length < 4 ? "— mínimo 4 dígitos" : ""}</p>
          <button onClick={submitManual} disabled={manualCode.length < 4} style={{ background: manualCode.length >= 4 ? BLUE : "#C7CEDA" }} className="w-full mt-2 text-white text-sm font-semibold py-2.5 rounded-lg">
            Confirmar código
          </button>
          {status !== "erro" && status !== "sem-suporte" && (
            <button onClick={() => setManualMode(false)} style={{ color: T.subtext }} className="w-full mt-2 text-xs py-1">Voltar para a câmera</button>
          )}
        </div>
      )}

      <button onClick={() => { pararTudo(); onCancel(); }} style={{ color: T.subtext }} className="w-full mt-3 text-xs py-2">Cancelar</button>
    </div>
  );
}

function CornerGuide({ className }) {
  return <div className={`absolute h-5 w-5 border-t-[3px] border-l-[3px] rounded-tl-md ${className}`} style={{ borderColor: RED }} />;
}

// ============ Confirmar produto ============
function ConfirmProductView({ T, barcode, initial, wasKnown, onCancel, onContinue }) {
  const [nome, setNome] = useState(initial.nome || "");
  const [setor, setSetor] = useState(initial.setor || "");
  const [setorCustom, setSetorCustom] = useState("");
  const [foto, setFoto] = useState(initial.foto || null);
  const [buscando, setBuscando] = useState(!wasKnown);
  const [origem, setOrigem] = useState(wasKnown ? "catalogo" : null);
  const [carregandoFoto, setCarregandoFoto] = useState(false);
  const cameraInputRef = useRef(null);
  const galeriaInputRef = useRef(null);

  useEffect(() => {
    if (wasKnown) { setBuscando(false); return; }
    let cancelled = false;
    (async () => {
      const resultado = await buscarProdutoPorCodigo(barcode);
      if (!cancelled) {
        if (resultado) {
          setNome(resultado.nome);
          setOrigem("api");
          if (resultado.foto) setFoto((atual) => atual || resultado.foto);
        }
        setBuscando(false);
      }
    })();
    return () => { cancelled = true; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [barcode, wasKnown]);

  async function handleFotoSelecionada(e) {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    setCarregandoFoto(true);
    try { setFoto(await compressImage(file)); } catch {}
    setCarregandoFoto(false);
    e.target.value = "";
  }

  const setorFinal = setor === "Outro" ? setorCustom.trim() : setor;
  const podeContinuar = nome.trim().length > 0 && setorFinal.length > 0;

  return (
    <div className="px-4 pt-4">
      <div style={{ background: T.card, borderColor: T.border }} className="rounded-xl p-4 border shadow-sm mb-4">
        <div style={{ color: T.subtext }} className="flex items-center gap-2 text-xs mb-1"><Barcode size={13} /> Código escaneado</div>
        <p className="font-mono font-semibold text-base">{barcode}</p>
      </div>

      {buscando && (
        <div style={{ color: T.subtext }} className="flex items-center gap-2 text-xs mb-4 px-1">
          <Loader2 size={14} className="animate-spin" color={BLUE} /> Buscando nome do produto em português...
        </div>
      )}
      {!buscando && origem === "catalogo" && (
        <div style={{ background: BLUE_SOFT, color: BLUE_DARK }} className="text-xs font-medium px-3 py-2 rounded-lg mb-4 flex items-center gap-1.5">
          <Check size={13} /> Produto já cadastrado — dados preenchidos automaticamente.
        </div>
      )}
      {!buscando && origem === "api" && (
        <div style={{ background: BLUE_SOFT, color: BLUE_DARK }} className="text-xs font-medium px-3 py-2 rounded-lg mb-4 flex items-center gap-1.5">
          <Check size={13} /> Nome localizado automaticamente. Confira antes de continuar.
        </div>
      )}
      {!buscando && !origem && (
        <div style={{ background: RED_SOFT, color: RED_DARK }} className="text-xs font-medium px-3 py-2 rounded-lg mb-4 flex items-center gap-1.5">
          <AlertTriangle size={13} /> Produto não encontrado. Preencha os dados manualmente.
        </div>
      )}

      <div style={{ background: T.card, borderColor: T.border }} className="rounded-xl p-4 border shadow-sm flex flex-col gap-4">
        <div>
          <label style={{ color: T.subtext }} className="text-xs font-semibold mb-1.5 block">Foto do produto</label>
          <div className="flex items-center gap-3">
            {foto ? <img src={foto} alt="" className="h-16 w-16 rounded-lg object-cover" /> : (
              <div style={{ background: T.chipBg }} className="h-16 w-16 rounded-lg flex items-center justify-center"><ImageOff size={20} color={T.subtext} /></div>
            )}
            <div className="flex flex-col gap-1.5 flex-1">
              <div className="flex gap-1.5">
                <button onClick={() => cameraInputRef.current && cameraInputRef.current.click()} disabled={carregandoFoto}
                  style={{ background: BLUE_SOFT, color: BLUE_DARK }} className="flex-1 text-xs font-medium py-2 rounded-lg flex items-center justify-center gap-1.5">
                  {carregandoFoto ? <Loader2 size={13} className="animate-spin" /> : <Camera size={13} />} Tirar foto
                </button>
                <button onClick={() => galeriaInputRef.current && galeriaInputRef.current.click()} disabled={carregandoFoto}
                  style={{ background: T.chipBg, color: T.text }} className="flex-1 text-xs font-medium py-2 rounded-lg flex items-center justify-center gap-1.5">
                  <Images size={13} /> Galeria
                </button>
              </div>
              {foto && <button onClick={() => setFoto(null)} style={{ color: RED_DARK }} className="text-[11px] font-medium text-left">Remover foto</button>}
            </div>
            <input ref={cameraInputRef} type="file" accept="image/*" capture="environment" className="hidden" onChange={handleFotoSelecionada} />
            <input ref={galeriaInputRef} type="file" accept="image/*" className="hidden" onChange={handleFotoSelecionada} />
          </div>
        </div>

        <div>
          <label style={{ color: T.subtext }} className="text-xs font-semibold mb-1.5 block">Nome do produto</label>
          <input value={nome} maxLength={120} onChange={(e) => setNome(sanitizarTexto(e.target.value, 120))} placeholder="Ex: Leite integral 1L"
            style={{ background: T.inputBg, color: T.text, borderColor: T.border }} className="w-full border rounded-lg px-3 py-2.5 text-sm outline-none focus:ring-2" />
        </div>
        <div>
          <label style={{ color: T.subtext }} className="text-xs font-semibold mb-1.5 block">Setor <span style={{ color: RED }}>*</span></label>
          <div className="grid grid-cols-2 gap-2">
            {SETORES.map((s) => (
              <button key={s} onClick={() => setSetor(s)}
                style={setor === s ? { background: BLUE, color: "#fff", borderColor: BLUE } : { background: T.inputBg, color: T.text, borderColor: T.border }}
                className="text-xs font-medium px-2.5 py-2 rounded-lg border text-left">
                {s}
              </button>
            ))}
          </div>
          {setor === "Outro" && (
            <input value={setorCustom} maxLength={40} onChange={(e) => setSetorCustom(sanitizarTexto(e.target.value, 40))} placeholder="Digite o setor"
              style={{ background: T.inputBg, color: T.text, borderColor: T.border }} className="w-full mt-2 border rounded-lg px-3 py-2.5 text-sm outline-none focus:ring-2" />
          )}
        </div>
      </div>

      <div className="flex gap-2 mt-5">
        <button onClick={onCancel} style={{ color: T.subtext, borderColor: T.border }} className="flex-1 text-sm font-medium py-3 rounded-xl border">Cancelar</button>
        <button disabled={!podeContinuar} onClick={() => onContinue({ nome: nome.trim(), setor: setorFinal, foto })}
          style={{ background: podeContinuar ? RED : "#E9CBCC" }} className="flex-[2] text-sm font-semibold py-3 rounded-xl text-white flex items-center justify-center gap-1.5">
          Avançar <ChevronRight size={16} />
        </button>
      </div>
    </div>
  );
}

// ============ Validade ============
function ExpiryView({ T, product, barcode, editing, items, onCancel, onSave }) {
  const [validade, setValidade] = useState(editing ? editing.validade : "");
  const [diasAlerta, setDiasAlerta] = useState(editing ? editing.diasAlerta : 15);
  const [quantidade, setQuantidade] = useState(editing ? editing.quantidade || 1 : 1);
  const [precoUnitario, setPrecoUnitario] = useState(editing ? editing.precoUnitario || "" : "");
  const [observacoes, setObservacoes] = useState(editing ? editing.observacoes || "" : "");
  const [confirmarDuplicado, setConfirmarDuplicado] = useState(false);

  const { opcoes, restritivo, diasRestantesAtual } = useMemo(() => calcularOpcoesAlerta(validade), [validade]);

  useEffect(() => {
    if (opcoes.length && !opcoes.includes(diasAlerta)) setDiasAlerta(opcoes[opcoes.length - 1]);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [validade]);

  const podeSalvar = !!validade && opcoes.length > 0;
  const valorTotal = (Number(quantidade) || 0) * (Number(precoUnitario) || 0);

  const duplicado = !editing && validade
    ? items.some((i) => i.barcode === barcode && i.validade === validade)
    : false;

  function handleSalvar() {
    if (duplicado && !confirmarDuplicado) { setConfirmarDuplicado(true); return; }
    onSave({
      validade, diasAlerta,
      quantidade: clampNumero(quantidade, 1, 99999),
      precoUnitario: clampNumero(precoUnitario, 0, 999999),
      observacoes: sanitizarTexto(observacoes.trim(), 300)
    });
  }

  return (
    <div className="px-4 pt-4">
      <div style={{ background: T.card, borderColor: T.border }} className="rounded-xl p-4 border shadow-sm mb-4 flex items-center gap-3">
        <Thumb foto={product.foto} size={44} />
        <div className="min-w-0">
          <p className="font-semibold text-sm truncate">{product.nome}</p>
          <div className="flex items-center gap-3 mt-1">
            <span style={{ color: T.subtext }} className="inline-flex items-center gap-1 text-[11px]"><MapPin size={11} /> {product.setor}</span>
            <span style={{ color: T.subtext }} className="inline-flex items-center gap-1 text-[11px] font-mono"><Barcode size={11} /> {barcode}</span>
          </div>
        </div>
      </div>

      <div style={{ background: T.card, borderColor: T.border }} className="rounded-xl p-4 border shadow-sm flex flex-col gap-4">
        <div>
          <label style={{ color: T.subtext }} className="text-xs font-semibold mb-1.5 flex items-center gap-1.5"><Calendar size={13} /> Data de validade</label>
          <input type="date" value={validade} onChange={(e) => setValidade(e.target.value)}
            style={{ background: T.inputBg, color: T.text, borderColor: T.border }} className="w-full border rounded-lg px-3 py-2.5 text-sm outline-none focus:ring-2" />
        </div>

        <div>
          <label style={{ color: T.subtext }} className="text-xs font-semibold mb-1.5 flex items-center gap-1.5"><Clock size={13} /> Avisar quantos dias antes de vencer?</label>

          {validade && diasRestantesAtual !== null && diasRestantesAtual <= 0 ? (
            <div style={{ background: RED_SOFT, color: RED_DARK }} className="text-xs font-medium px-3 py-2.5 rounded-lg flex items-start gap-2">
              <AlertTriangle size={14} className="mt-0.5 shrink-0" />
              <span>{diasRestantesAtual === 0 ? "Este produto vence hoje." : "Esta data já está vencida."} Não é possível definir uma antecedência de alerta — recomendamos registrar a baixa assim que possível.</span>
            </div>
          ) : (
            <>
              <div className="grid grid-cols-6 gap-1.5">
                {DIAS_ALERTA_BASE.map((n) => {
                  const habilitado = opcoes.includes(n);
                  return (
                    <button key={n} disabled={!habilitado} onClick={() => setDiasAlerta(n)}
                      style={
                        !habilitado ? { background: T.chipBg, color: T.subtext, opacity: 0.4, borderColor: T.border } :
                        diasAlerta === n ? { background: RED, color: "#fff", borderColor: RED } :
                        { background: T.inputBg, color: T.text, borderColor: T.border }
                      }
                      className="text-sm font-semibold py-2.5 rounded-lg border">
                      {n}
                    </button>
                  );
                })}
              </div>
              {restritivo && opcoes.length > 0 && (
                <div style={{ background: RED_SOFT, color: RED_DARK }} className="text-[11px] font-medium px-3 py-2 rounded-lg mt-2 flex items-start gap-1.5">
                  <ShieldAlert size={13} className="mt-0.5 shrink-0" />
                  <span>Faltam apenas {diasRestantesAtual} dia(s) para o vencimento — por segurança, só é possível escolher {opcoes[0]} dia(s) de antecedência para este produto.</span>
                </div>
              )}
              {!restritivo && <p style={{ color: T.subtext }} className="text-[11px] mt-1.5">Selecione entre 10 e 15 dias.</p>}
            </>
          )}
        </div>

        <div className="grid grid-cols-2 gap-3">
          <div>
            <label style={{ color: T.subtext }} className="text-xs font-semibold mb-1.5 block">Quantidade</label>
            <input type="number" inputMode="numeric" min="1" max="99999" value={quantidade}
              onChange={(e) => setQuantidade(e.target.value.replace(/[^\d]/g, ""))}
              onBlur={(e) => setQuantidade(clampNumero(e.target.value, 1, 99999))}
              style={{ background: T.inputBg, color: T.text, borderColor: T.border }} className="w-full border rounded-lg px-3 py-2.5 text-sm outline-none focus:ring-2" />
          </div>
          <div>
            <label style={{ color: T.subtext }} className="text-xs font-semibold mb-1.5 block">Preço unitário (R$)</label>
            <input type="number" inputMode="decimal" min="0" step="0.01" value={precoUnitario}
              onChange={(e) => setPrecoUnitario(e.target.value)}
              onBlur={(e) => setPrecoUnitario(e.target.value === "" ? "" : clampNumero(e.target.value, 0, 999999))}
              placeholder="0,00" style={{ background: T.inputBg, color: T.text, borderColor: T.border }} className="w-full border rounded-lg px-3 py-2.5 text-sm outline-none focus:ring-2" />
          </div>
        </div>
        {valorTotal > 0 && <p style={{ color: T.subtext }} className="text-[11px] -mt-2">Valor total estimado: <strong style={{ color: T.text }}>{formatarMoeda(valorTotal)}</strong></p>}

        <div>
          <div className="flex items-center justify-between mb-1.5">
            <label style={{ color: T.subtext }} className="text-xs font-semibold block">Observações (opcional)</label>
            <span style={{ color: T.subtext }} className="text-[10px]">{observacoes.length}/300</span>
          </div>
          <textarea value={observacoes} maxLength={300} onChange={(e) => setObservacoes(e.target.value)} rows={2} placeholder="Ex: prateleira 3, lote da promoção..."
            style={{ background: T.inputBg, color: T.text, borderColor: T.border }} className="w-full border rounded-lg px-3 py-2.5 text-sm outline-none focus:ring-2 resize-none" />
        </div>

        {duplicado && (
          <div style={{ background: RED_SOFT, color: RED_DARK }} className="text-xs font-medium px-3 py-2 rounded-lg flex items-start gap-2">
            <AlertTriangle size={14} className="mt-0.5 shrink-0" />
            <span>Já existe um produto com este código e esta mesma validade cadastrado. Confirme novamente para salvar mesmo assim.</span>
          </div>
        )}
      </div>

      <div className="flex gap-2 mt-5">
        <button onClick={onCancel} style={{ color: T.subtext, borderColor: T.border }} className="flex-1 text-sm font-medium py-3 rounded-xl border">Cancelar</button>
        <button disabled={!podeSalvar} onClick={handleSalvar}
          style={{ background: podeSalvar ? BLUE : "#C7CEDA" }} className="flex-[2] text-sm font-semibold py-3 rounded-xl text-white flex items-center justify-center gap-1.5">
          <Check size={16} /> {editing ? "Salvar alterações" : duplicado && confirmarDuplicado ? "Salvar mesmo assim" : "Salvar alerta"}
        </button>
      </div>
    </div>
  );
}

// ============ Histórico ============
function HistoricoView({ T, historico }) {
  const [periodo, setPeriodo] = useState(30);

  const filtrado = useMemo(() => {
    const limite = Date.now() - periodo * 86400000;
    return historico.filter((h) => new Date(h.dataBaixa).getTime() >= limite);
  }, [historico, periodo]);

  const valorPerdido = filtrado.filter((h) => h.motivo === "Vencido").reduce((acc, h) => acc + (Number(h.quantidade) || 1) * (Number(h.precoUnitario) || 0), 0);

  const dadosGrafico = useMemo(() => {
    const mapa = {};
    filtrado.forEach((h) => { mapa[h.setor] = (mapa[h.setor] || 0) + 1; });
    return Object.entries(mapa).sort((a, b) => b[1] - a[1]).slice(0, 6).map(([setor, qtd]) => ({ setor, qtd }));
  }, [filtrado]);

  const rankingResponsaveis = useMemo(() => {
    const mapa = {};
    filtrado.forEach((h) => { const nome = h.registradoPor || "Não identificado"; mapa[nome] = (mapa[nome] || 0) + 1; });
    return Object.entries(mapa).sort((a, b) => b[1] - a[1]).slice(0, 5);
  }, [filtrado]);
  const maxResp = rankingResponsaveis.length ? rankingResponsaveis[0][1] : 1;

  function exportarCSV() {
    const header = ["Produto", "Setor", "Código", "Validade", "Motivo", "Quantidade", "PrecoUnitario", "DataBaixa"];
    const rows = filtrado.map((h) => [h.nome, h.setor, h.barcode, formatarData(h.validade), h.motivo, h.quantidade || 1, (h.precoUnitario || 0).toFixed(2), formatarDataHora(h.dataBaixa)]);
    downloadCSV(rows, header, "condor-historico-baixas.csv");
  }
  function exportarPlanilha(formato) {
    const linhas = filtrado.map((h) => ({
      Produto: h.nome, Setor: h.setor, Codigo: h.barcode, Validade: formatarData(h.validade),
      Motivo: h.motivo, Quantidade: h.quantidade || 1, PrecoUnitario: h.precoUnitario || 0, DataBaixa: formatarDataHora(h.dataBaixa)
    }));
    downloadPlanilha(linhas, `condor-historico-baixas.${formato}`, "Historico");
  }

  return (
    <div className="px-4 pt-4">
      <div style={{ background: `linear-gradient(135deg, ${RED_DARK} 0%, ${BLUE_DARK} 100%)` }} className="rounded-xl px-4 py-3.5 mb-4 flex items-center gap-3">
        <div className="h-9 w-9 rounded-lg bg-white/15 flex items-center justify-center shrink-0"><DollarSign size={17} color="#fff" /></div>
        <div>
          <p className="text-white/75 text-[11px] font-medium">Perda registrada (vencidos · {periodo}d)</p>
          <p className="text-white font-extrabold text-lg leading-tight">{formatarMoeda(valorPerdido)}</p>
        </div>
      </div>

      <div className="flex items-center gap-2 mb-4 flex-wrap">
        {[7, 30, 90].map((p) => (
          <button key={p} onClick={() => setPeriodo(p)} style={periodo === p ? { background: BLUE, color: "#fff" } : { background: T.chipBg, color: T.text }} className="text-xs font-medium px-3 py-1.5 rounded-full">
            {p} dias
          </button>
        ))}
        <div className="ml-auto flex gap-1.5">
          <button onClick={exportarCSV} title="Exportar CSV" style={{ background: T.card, borderColor: T.border, color: T.text }} className="text-[11px] font-medium px-2.5 py-1.5 rounded-full border flex items-center gap-1"><Download size={12} /> CSV</button>
          <button onClick={() => exportarPlanilha("ods")} title="Exportar para LibreOffice" style={{ background: T.card, borderColor: T.border, color: T.text }} className="text-[11px] font-medium px-2.5 py-1.5 rounded-full border flex items-center gap-1"><FileSpreadsheet size={12} /> ODS</button>
        </div>
      </div>

      {dadosGrafico.length > 0 && (
        <div style={{ background: T.card, borderColor: T.border }} className="rounded-xl p-3.5 border shadow-sm mb-4">
          <p style={{ color: T.subtext }} className="text-[11px] font-semibold mb-2 uppercase tracking-wide">Baixas por setor</p>
          <ResponsiveContainer width="100%" height={160}>
            <BarChart data={dadosGrafico} margin={{ top: 4, right: 4, left: -24, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" stroke={T.border} vertical={false} />
              <XAxis dataKey="setor" tick={{ fontSize: 9, fill: T.subtext }} interval={0} angle={-20} textAnchor="end" height={40} />
              <YAxis allowDecimals={false} tick={{ fontSize: 10, fill: T.subtext }} />
              <Tooltip contentStyle={{ fontSize: 12, borderRadius: 8 }} />
              <Bar dataKey="qtd" fill={RED} radius={[4, 4, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      )}

      {rankingResponsaveis.length > 0 && (
        <div style={{ background: T.card, borderColor: T.border }} className="rounded-xl p-3.5 border shadow-sm mb-4">
          <p style={{ color: T.subtext }} className="text-[11px] font-semibold mb-2 uppercase tracking-wide flex items-center gap-1.5"><Users2 size={12} /> Baixas por responsável</p>
          <div className="flex flex-col gap-1.5">
            {rankingResponsaveis.map(([nome, qtd]) => (
              <div key={nome} className="flex items-center gap-2">
                <span className="text-[11px] w-28 truncate">{nome}</span>
                <div style={{ background: T.chipBg }} className="flex-1 h-2 rounded-full overflow-hidden">
                  <div style={{ width: `${(qtd / maxResp) * 100}%`, background: BLUE }} className="h-full rounded-full" />
                </div>
                <span className="text-[11px] font-semibold w-4 text-right">{qtd}</span>
              </div>
            ))}
          </div>
        </div>
      )}

      <div style={{ background: BLUE_SOFT, color: BLUE_DARK }} className="rounded-xl px-3.5 py-3 mb-4 flex items-start gap-2.5">
        <Info size={15} className="mt-0.5 shrink-0" />
        <p className="text-[11px] leading-relaxed">
          Referência do setor: o vencimento de validade responde por cerca de 38% das perdas em supermercados
          brasileiros, geralmente entre 1% e 1,5% do faturamento. Acompanhar esse histórico de perto ajuda a manter
          sua loja abaixo dessa média.
        </p>
      </div>

      {filtrado.length === 0 ? (
        <div className="text-center py-14 px-6">
          <div style={{ background: BLUE_SOFT }} className="h-16 w-16 rounded-2xl mx-auto flex items-center justify-center mb-3"><History size={26} color={BLUE} /></div>
          <p className="font-semibold text-sm">Nenhuma baixa neste período</p>
          <p style={{ color: T.subtext }} className="text-xs mt-1">Baixas registradas na tela inicial aparecem aqui.</p>
        </div>
      ) : (
        <div className="flex flex-col gap-2.5">
          {filtrado.map((h) => (
            <div key={h.id + h.dataBaixa} style={{ background: T.card, borderColor: T.border }} className="rounded-xl p-3 border shadow-sm flex items-center gap-3">
              <Thumb foto={h.foto} size={40} />
              <div className="flex-1 min-w-0">
                <p className="font-medium text-sm truncate">{h.nome}</p>
                <p style={{ color: T.subtext }} className="text-[11px] mt-0.5">{h.setor} · {formatarDataHora(h.dataBaixa)}</p>
                {h.registradoPor && <p style={{ color: T.subtext }} className="text-[10px] mt-0.5">Por {h.registradoPor}</p>}
              </div>
              <span style={h.motivo === "Vencido" ? { background: RED_SOFT, color: RED_DARK } : { background: BLUE_SOFT, color: BLUE_DARK }} className="text-[10px] font-bold px-2 py-1 rounded-md shrink-0">
                {h.motivo}
              </span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// ============ Ajustes ============
function AjustesView({ T, dark, setDark, som, setSom, notifPermission, onToggleNotif, items, historico, catalog, pin, onDefinirPin, onRestaurarBackup, showToast, usuario, onTrocarUsuario }) {
  const [pinInput, setPinInput] = useState("");
  const [confirmarRestauro, setConfirmarRestauro] = useState(null);
  const backupInputRef = useRef(null);
  const iosSemInstalar = isIOS() && !isStandalone();

  function exportarAtivos(formato) {
    if (formato === "csv") {
      const header = ["Produto", "Setor", "Código", "Validade", "DiasAlerta", "Quantidade", "PrecoUnitario", "Observacoes"];
      const rows = items.map((i) => [i.nome, i.setor, i.barcode, formatarData(i.validade), i.diasAlerta, i.quantidade || 1, (i.precoUnitario || 0).toFixed(2), i.observacoes || ""]);
      downloadCSV(rows, header, "condor-produtos-monitorados.csv");
    } else {
      const linhas = items.map((i) => ({
        Produto: i.nome, Setor: i.setor, Codigo: i.barcode, Validade: formatarData(i.validade),
        DiasAlerta: i.diasAlerta, Quantidade: i.quantidade || 1, PrecoUnitario: i.precoUnitario || 0, Observacoes: i.observacoes || ""
      }));
      downloadPlanilha(linhas, `condor-produtos-monitorados.${formato}`, "Produtos");
    }
  }

  function exportarBackupCompleto() {
    downloadJSON({ versao: 1, dataExportacao: new Date().toISOString(), catalog, items, historico }, `condor-backup-${new Date().toISOString().slice(0, 10)}.json`);
  }

  function handleArquivoBackup(e) {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      try {
        const dados = JSON.parse(ev.target.result);
        if (!dados || (!dados.items && !dados.catalog && !dados.historico)) { showToast("Arquivo de backup inválido.", "warn"); return; }
        setConfirmarRestauro(dados);
      } catch { showToast("Não foi possível ler o arquivo de backup.", "warn"); }
    };
    reader.readAsText(file);
    e.target.value = "";
  }

  function salvarPin() {
    if (pinInput.length !== 4) { showToast("O PIN deve ter 4 dígitos.", "warn"); return; }
    onDefinirPin(pinInput);
    setPinInput("");
  }

  const Row = ({ icon: Icon, title, desc, right, children }) => (
    <div style={{ background: T.card, borderColor: T.border }} className="rounded-xl p-3.5 border shadow-sm">
      <div className="flex items-center gap-3">
        <div style={{ background: BLUE_SOFT }} className="h-9 w-9 rounded-lg flex items-center justify-center shrink-0"><Icon size={16} color={BLUE} /></div>
        <div className="flex-1 min-w-0">
          <p className="text-sm font-semibold">{title}</p>
          {desc && <p style={{ color: T.subtext }} className="text-[11px] mt-0.5">{desc}</p>}
        </div>
        {right}
      </div>
      {children}
    </div>
  );
  const Switch = ({ ativo, onClick }) => (
    <button onClick={onClick} style={{ background: ativo ? BLUE : T.chipBg }} className="w-11 h-6 rounded-full relative transition shrink-0">
      <span style={{ left: ativo ? 22 : 3, background: "#fff" }} className="absolute top-0.5 h-5 w-5 rounded-full transition-all shadow" />
    </button>
  );

  return (
    <div className="px-4 pt-4 flex flex-col gap-2.5">
      <Row icon={dark ? Sun : Moon} title="Tema escuro" desc="Alterna as cores do aplicativo" right={<Switch ativo={dark} onClick={() => setDark(!dark)} />} />
      <Row icon={som ? Volume2 : VolumeX} title="Som ao bipar" desc="Toca um beep e vibra ao escanear" right={<Switch ativo={som} onClick={() => setSom(!som)} />} />
      <Row icon={Users2} title="Seu nome" desc={usuario ? `Registrando ações como "${usuario}"` : "Ainda não identificado"}
        right={<button onClick={onTrocarUsuario} style={{ background: BLUE_SOFT, color: BLUE_DARK }} className="text-[11px] font-semibold px-3 py-1.5 rounded-full">{usuario ? "Trocar" : "Definir"}</button>} />

      <Row icon={notifPermission === "granted" ? Bell : BellOff} title="Notificações do navegador"
        desc={notifPermission === "granted" ? "Ativadas neste dispositivo" : iosSemInstalar ? "No iPhone, precisa instalar o app primeiro" : "Avise quando um produto entrar em alerta"}
        right={notifPermission !== "granted" && <button onClick={onToggleNotif} style={{ background: BLUE, color: "#fff" }} className="text-[11px] font-semibold px-3 py-1.5 rounded-full">Ativar</button>}>
        {iosSemInstalar && notifPermission !== "granted" && (
          <div style={{ background: RED_SOFT, color: RED_DARK }} className="mt-3 rounded-lg px-3 py-2.5 text-[11px] leading-relaxed">
            No iPhone, as notificações só funcionam depois de instalar o app: toque em <strong>Compartilhar</strong> na
            barra do Safari → <strong>Adicionar à Tela de Início</strong> → abra o app pelo ícone criado → aí sim toque
            em "Ativar" aqui dentro.
          </div>
        )}
      </Row>
      <Row icon={Users2} title="Dados compartilhados" desc="Produtos e histórico são visíveis para toda a equipe que acessa este app." />

      <Row icon={Lock} title="Bloqueio por PIN" desc={pin ? "Ativo neste dispositivo" : "Peça o PIN antes de abrir o app"} right={pin && <button onClick={() => onDefinirPin(null)} style={{ background: RED_SOFT, color: RED_DARK }} className="text-[11px] font-semibold px-3 py-1.5 rounded-full">Remover</button>}>
        {!pin && (
          <div className="flex gap-2 mt-3">
            <input value={pinInput} onChange={(e) => setPinInput(apenasNumeros(e.target.value, 4))} inputMode="numeric" maxLength={4} placeholder="0000"
              style={{ background: T.inputBg, color: T.text, borderColor: T.border }} className="flex-1 border rounded-lg px-3 py-2 text-sm font-mono tracking-widest outline-none focus:ring-2" />
            <button onClick={salvarPin} style={{ background: BLUE, color: "#fff" }} className="text-xs font-semibold px-4 rounded-lg">Definir</button>
          </div>
        )}
      </Row>

      <p style={{ color: T.subtext }} className="text-[11px] font-semibold mt-3 mb-1 px-1 uppercase tracking-wide">Relatórios e exportação</p>
      <Row icon={FileText} title="Produtos monitorados" desc={`${items.length} produto(s) na lista ativa`}
        right={
          <div className="flex gap-1.5">
            <button onClick={() => exportarAtivos("csv")} title="CSV" style={{ background: BLUE_SOFT, color: BLUE_DARK }} className="h-8 px-2 rounded-lg flex items-center justify-center text-[10px] font-semibold">CSV</button>
            <button onClick={() => exportarAtivos("ods")} title="LibreOffice" style={{ background: BLUE_SOFT, color: BLUE_DARK }} className="h-8 px-2 rounded-lg flex items-center justify-center text-[10px] font-semibold">ODS</button>
            <button onClick={() => exportarAtivos("xlsx")} title="Excel" style={{ background: BLUE_SOFT, color: BLUE_DARK }} className="h-8 px-2 rounded-lg flex items-center justify-center text-[10px] font-semibold">XLSX</button>
          </div>
        } />
      <Row icon={History} title="Total de baixas registradas" desc={`${historico.length} baixa(s) no histórico completo`} />

      <p style={{ color: T.subtext }} className="text-[11px] font-semibold mt-3 mb-1 px-1 uppercase tracking-wide">Backup dos dados</p>
      <Row icon={Upload} title="Backup completo (JSON)" desc="Exporte ou restaure todos os produtos, catálogo e histórico"
        right={<button onClick={exportarBackupCompleto} style={{ background: BLUE_SOFT, color: BLUE_DARK }} className="h-8 w-8 rounded-lg flex items-center justify-center"><Download size={14} /></button>}>
        <button onClick={() => backupInputRef.current && backupInputRef.current.click()} style={{ background: T.chipBg, color: T.text }} className="w-full mt-3 text-xs font-medium py-2 rounded-lg">
          Restaurar backup a partir de arquivo
        </button>
        <input ref={backupInputRef} type="file" accept="application/json" className="hidden" onChange={handleArquivoBackup} />
        {confirmarRestauro && (
          <div style={{ background: RED_SOFT }} className="mt-3 rounded-lg p-3">
            <p style={{ color: RED_DARK }} className="text-[11px] font-medium">Isso vai substituir os dados atuais compartilhados pela equipe. Deseja continuar?</p>
            <div className="flex gap-2 mt-2">
              <button onClick={() => setConfirmarRestauro(null)} style={{ color: T.subtext }} className="flex-1 text-[11px] font-medium py-1.5">Cancelar</button>
              <button onClick={() => { onRestaurarBackup(confirmarRestauro); setConfirmarRestauro(null); }} style={{ background: RED_DARK, color: "#fff" }} className="flex-1 text-[11px] font-semibold py-1.5 rounded-lg">Confirmar restauração</button>
            </div>
          </div>
        )}
      </Row>

      <div style={{ background: T.card, borderColor: T.border }} className="rounded-xl p-5 border shadow-sm mt-3 flex flex-col items-center text-center">
        <img src={LOGO_SRC} alt="Condor Supermercados" className="h-8 w-auto mb-2" />
        <p className="text-sm font-semibold">Alerta de Validade</p>
        <p style={{ color: T.subtext }} className="text-[11px] mt-0.5">Versão 4.0 · Loja 79 · CPD</p>
        <p style={{ color: T.subtext }} className="text-[10px] mt-2">Reduza perdas por vencimento com câmera, alertas inteligentes, regras de segurança e histórico de baixas.</p>
      </div>
    </div>
  );
}
